            raise ConfigError("%s must be an object" % where)
        if set(element) != set(EVENT_FIELDS):
            raise ConfigError(
                "%s must contain exactly the fields at_ms, link, up" % where
            )
        at = parse_time_value(
            element["at_ms"], MAX_CLOCK_THOUSANDTHS, "%s.at_ms" % where
        )
