            )
        up = element["up"]
        if type(up) is not bool:
            raise ConfigError("%s.up must be a boolean" % where)
        if previous_at is not None and at < previous_at:
            raise ConfigError(
                "%s.at_ms is earlier than the previous event" % where
            )
        previous_at = at
        resolved.append((at, link_id, up))
    return resolved

